+        conn.pragma_update(None, "query_only", true).unwrap();
+        assert_eq!(conn.query_row("PRAGMA query_only", [], |r| r.get::<_,i64>(0)).unwrap(), 1);
+        let mut reports = Vec::new();
+        let mut prior = None;
+        for repeat in 0..2 {
+            let tx = conn.transaction().unwrap();
+            crate::audit_shadow_probe::reset();
+            let started = std::time::Instant::now();
+            let (result, events, work) = traced(true, || audit(&tx));
+            let elapsed = started.elapsed().as_nanos().to_string();
+            let counters = crate::audit_shadow_probe::snapshot();
